<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {message,Modal} from 'ant-design-vue'
import http from '@/api/request'
import FieldInput from './FieldInput.vue'
import type {SupplementField} from '@/api/supplement'
const props=defineProps<{open:boolean;channelCode:string;channelName:string}>()
const emit=defineEmits(['update:open'])
type Condition={field:string;value:any}
type Material={code:string;name:string;applicability:string;required:boolean;requiredWhen?:Condition;requiredWhenAll?:Condition[];rowScoped?:boolean}
type Section={key:string;title:string;stage:string;fields:SupplementField[];repeatable:boolean;materials:Material[];applicability:string;configurationPending?:boolean}
type Override={mode:string;applicability:string;materials:Material[]}
const loading=ref(false),saving=ref(false),dirty=ref(false),version=ref(0),defaults=ref<Section[]>([]),overrides=ref<Record<string,Override>>({}),active=ref(''),error=ref('')
const selected=computed(()=>defaults.value.find(s=>s.key===active.value)),custom=computed(()=>overrides.value[active.value]),visible=computed(()=>custom.value||selected.value)
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const url=computed(()=>`/api/supplement/config/channels/${encodeURIComponent(props.channelCode)}`)
async function load(){loading.value=true;error.value='';try{const r=(await http.get(url.value)).data;version.value=r.version;defaults.value=r.defaults;overrides.value=r.sections||{};active.value=defaults.value.find(s=>s.configurationPending)?.key||defaults.value[0]?.key||'';dirty.value=false}catch(e:any){error.value=e.message}finally{loading.value=false}}
watch(()=>[props.open,props.channelCode],()=>{if(props.open&&props.channelCode)load()},{immediate:true})
function customize(on:boolean){if(!selected.value)return;if(on){overrides.value[active.value]={mode:'CONFIGURED',applicability:selected.value.applicability||'',materials:clone(selected.value.materials)}}else delete overrides.value[active.value];dirty.value=true}
function modeChange(){if(custom.value?.mode==='NOT_APPLICABLE')custom.value.materials=[];dirty.value=true}
function rule(m:Material){return m.required?'ALWAYS':m.requiredWhen||m.requiredWhenAll?'CONDITION':'OPTIONAL'}
function setRule(m:Material,value:string){m.required=value==='ALWAYS';delete m.requiredWhen;delete m.requiredWhenAll;if(value==='CONDITION')m.requiredWhenAll=[{field:selected.value?.fields[0]?.key||'',value:''}];dirty.value=true}
function conditions(m:Material){if(m.requiredWhen)return [m.requiredWhen];return m.requiredWhenAll||[]}
function addCondition(m:Material){m.requiredWhenAll=[...conditions(m),{field:selected.value?.fields[0]?.key||'',value:''}];delete m.requiredWhen;dirty.value=true}
function removeCondition(m:Material,index:number){m.requiredWhenAll=conditions(m).filter((_,i)=>i!==index);delete m.requiredWhen;if(!m.requiredWhenAll.length)delete m.requiredWhenAll;dirty.value=true}
function fieldFor(key:string){return selected.value?.fields.find(f=>f.key===key)||{key,label:'条件值'}}
function addMaterial(){if(!custom.value)return;custom.value.materials.push({code:`CFG_${active.value}_${crypto.randomUUID().replace(/-/g,'').slice(0,16)}`,name:'',applicability:'',required:false,rowScoped:!!selected.value?.repeatable});dirty.value=true}
async function save(){const issues:string[]=[];for(const [key,s] of Object.entries(overrides.value)){const name=defaults.value.find(d=>d.key===key)?.title||key;if(!s.applicability.trim())issues.push(`${name}：请填写适用依据`);if(s.mode==='CONFIGURED'&&!s.materials.length)issues.push(`${name}：至少配置一项材料`);s.materials.forEach((m,i)=>{if(!m.name.trim()||!m.applicability.trim())issues.push(`${name}第 ${i+1} 项：材料名称与形成时点必填`);if(conditions(m).some(c=>!c.field||c.value===''||c.value==null))issues.push(`${name}第 ${i+1} 项：请完善必传条件`)})}if(issues.length){Modal.error({title:'请完善配置',content:issues.join('；')});return}Modal.confirm({title:`发布 ${props.channelName} 材料模板 v${version.value+1}`,content:'新模板用于后续草稿及新批次。已提交或已通过的历史版本保持原清单。',okText:'发布版本',onOk:async()=>{saving.value=true;try{await http.put(url.value,{version:version.value,sections:overrides.value});await load();message.success('渠道材料模板已发布')}catch(e:any){message.error(e.message)}finally{saving.value=false}}})}
function close(){if(!dirty.value){emit('update:open',false);return}Modal.confirm({title:'配置尚未发布',content:'关闭会放弃本次未发布修改。',okText:'放弃修改',onOk:()=>emit('update:open',false)})}
</script>
<template><a-drawer :open="open" :title="`${channelName} · 补录材料配置`" width="90%" :mask-closable="false" @close="close"><a-spin :spinning="loading"><a-alert v-if="error" type="error" :message="error" show-icon /><template v-else><div class="config-summary"><span>当前发布版本 <b>v{{version}}</b></span><span>配置仅调整材料要求，不改变项目业务信息及审批权限。</span></div><div class="config-layout"><nav><button v-for="s in defaults" :key="s.key" :class="{active:active===s.key}" @click="active=s.key"><span>{{s.title}}</span><small>{{overrides[s.key]?'已配置':s.configurationPending?'待配置':'默认规则'}}</small></button></nav><main v-if="selected&&visible"><header><h3>{{selected.title}}</h3><a-switch :checked="!!custom" checked-children="自定义" un-checked-children="默认" @change="customize(!!$event)" /></header><a-alert v-if="!custom" :message="selected.configurationPending?'需求文档未明确此渠道规则。启用自定义，配置材料或明确评估检查不适用。':'当前使用内置渠道规则；启用自定义后可调整并发布新版本。'" :type="selected.configurationPending?'warning':'info'" show-icon /><template v-if="custom"><div class="config-form"><label>适用方式<a-select v-model:value="custom.mode" style="width:100%" :options="[{label:'配置材料清单',value:'CONFIGURED'},...(selected.key==='inspection'?[{label:'评估检查不适用',value:'NOT_APPLICABLE'}]:[])]" @change="modeChange" /></label><label>适用依据 / 配置说明<a-textarea v-model:value="custom.applicability" :rows="2" placeholder="说明依据、适用项目及形成时点" @change="dirty=true" /></label></div><a-alert v-if="custom.mode==='NOT_APPLICABLE'" type="warning" message="发布后，本渠道的评估检查栏目将标记不适用，不计入缺失项。" show-icon /></template><template v-if="!custom||custom.mode==='CONFIGURED'"><div class="materials-toolbar"><b>材料清单 · {{visible.materials.length}} 项</b><a-button v-if="custom" size="small" @click="addMaterial">＋ 新增材料</a-button></div><a-empty v-if="!visible.materials.length" description="尚未配置材料" /><article v-for="(m,index) in visible.materials" :key="m.code" class="config-material"><div class="material-heading"><b>材料 {{index+1}}</b><a-popconfirm v-if="custom" title="从本次模板中移除此材料？历史提交版本仍保留。" @confirm="custom.materials.splice(index,1);dirty=true"><a-button danger type="link" size="small">移除</a-button></a-popconfirm></div><div class="config-fields"><label>材料名称<a-input v-model:value="m.name" :disabled="!custom" :maxlength="250" @change="dirty=true" /></label><label>上传要求<a-select :value="rule(m)" :disabled="!custom" style="width:100%" :options="[{label:'按需补充',value:'OPTIONAL'},{label:'适用阶段必传',value:'ALWAYS'},{label:'满足条件时必传',value:'CONDITION'}]" @change="setRule(m,String($event))" /></label><label class="wide">形成时点 / 上传说明<a-textarea v-model:value="m.applicability" :disabled="!custom" :rows="2" :maxlength="1000" @change="dirty=true" /></label></div><div v-if="conditions(m).length" class="conditions"><p>同时满足以下条件时必传{{selected.repeatable?'（按每条业务记录判断）':''}}</p><div v-for="(c,i) in conditions(m)" :key="i" class="condition"><a-select v-model:value="c.field" :disabled="!custom" :options="selected.fields.map(f=>({label:f.label,value:f.key}))" style="width:220px" @change="c.value='';dirty=true" /><span>等于</span><FieldInput v-model="c.value" :field="fieldFor(c.field)" :disabled="!custom" @update:model-value="dirty=true" /><a-button v-if="custom" type="link" danger @click="removeCondition(m,i)">移除</a-button></div><a-button v-if="custom" size="small" @click="addCondition(m)">＋ 增加条件</a-button></div><small class="scope">{{selected.repeatable?'附件须关联对应业务记录；条件按记录核对。':'附件按本栏目信息核对。'}}</small></article></template></main></div></template></a-spin><template #footer><div class="config-footer"><span>{{dirty?'有未发布修改':'已与当前版本同步'}}</span><a-button @click="close">关闭</a-button><a-button type="primary" :loading="saving" :disabled="loading||!!error||!dirty" @click="save">发布新版本</a-button></div></template></a-drawer></template>
<style scoped>.config-summary{display:flex;gap:24px;color:#708095;margin-bottom:18px}.config-layout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:20px}.config-layout nav{border-right:1px solid #e7edf3;padding-right:12px}.config-layout nav button{display:flex;justify-content:space-between;gap:6px;width:100%;padding:12px 8px;border:0;border-radius:4px;background:none;cursor:pointer;text-align:left}.config-layout nav button.active{background:#eaf3fc;color:#1266ae}.config-layout nav small{color:#8896a7;font-size:11px}.config-layout main{min-width:0}.config-layout header,.materials-toolbar,.material-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.config-form{display:grid;gap:12px;margin-top:16px}.config-form label,.config-fields label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:#64748b}.config-form label:first-child{max-width:260px}.materials-toolbar{margin-top:20px}.config-material{border:1px solid #e1e8f0;padding:14px;margin-bottom:14px;border-radius:6px}.config-fields{display:grid;grid-template-columns:2fr 1fr;gap:14px}.wide{grid-column:1/-1}.conditions{background:#f6f8fb;padding:12px;margin-top:12px;font-size:12px}.condition{display:flex;align-items:center;gap:10px;margin:8px 0}.condition>:nth-child(3){flex:1}.scope{display:block;color:#8592a3;margin-top:10px}.config-footer{display:flex;justify-content:flex-end;align-items:center;gap:12px}.config-footer span{margin-right:auto;color:#7a8797}@media(max-width:800px){.config-layout{grid-template-columns:1fr}.config-fields{grid-template-columns:1fr}.condition{flex-wrap:wrap}}
</style>

